// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/places", wrapper.SearchPlaces)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/places/{id}", wrapper.GetPlace)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/places/{id}/pois", wrapper.ListPlacePois)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/places/{id}/guide", wrapper.GetPlaceGuide)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/pois/{type}/{id}", wrapper.GetPoi)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/hotels/link", wrapper.GetHotelsLink)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/hotels/go", wrapper.GoToHotels)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/car-hubs", wrapper.ListCarHubs)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/trips", wrapper.SearchTrips)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/explore", wrapper.ExploreDestinations)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/stay-prices", wrapper.ListStayPrices)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/weather", wrapper.GetWeather)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/routes/drive", wrapper.GetDriveRoute)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/routes/road", wrapper.GetRoadRoute)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/routes/road/pois", wrapper.ListRoadPois)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/geocode", wrapper.Geocode)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/transfers", wrapper.ListTransfers)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/favorites", wrapper.ListFavorites)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/favorites", wrapper.AddFavorite)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/favorites/{id}", wrapper.DeleteFavorite)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/favorites/{id}/current", wrapper.GetFavoriteCurrent)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/link-preview", wrapper.GetLinkPreview)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/favorites/{id}/items", wrapper.ListTripItems)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/favorites/{id}/items", wrapper.AddTripItem)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/favorites/{id}/items/{item_id}", wrapper.DeleteTripItem)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/favorites/{id}/items/{item_id}", wrapper.UpdateTripItem)
	})

	return r
}

