// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListCarHubs Аэропорты, до которых можно доехать на машине, и расходы на дорогу
	// (GET /car-hubs)
	ListCarHubs(ctx context.Context, request ListCarHubsRequestObject) (ListCarHubsResponseObject, error)
	// ExploreDestinations Куда угодно — самые дешёвые поездки из дома во все города
	// (GET /explore)
	ExploreDestinations(ctx context.Context, request ExploreDestinationsRequestObject) (ExploreDestinationsResponseObject, error)
	// ListFavorites Избранные маршруты текущего пользователя
	// (GET /favorites)
	ListFavorites(ctx context.Context, request ListFavoritesRequestObject) (ListFavoritesResponseObject, error)
	// AddFavorite Добавить маршрут в избранное
	// (POST /favorites)
	AddFavorite(ctx context.Context, request AddFavoriteRequestObject) (AddFavoriteResponseObject, error)
	// DeleteFavorite Убрать из избранного
	// (DELETE /favorites/{id})
	DeleteFavorite(ctx context.Context, request DeleteFavoriteRequestObject) (DeleteFavoriteResponseObject, error)
	// GetFavoriteCurrent Актуальная цена избранного маршрута
	// (GET /favorites/{id}/current)
	GetFavoriteCurrent(ctx context.Context, request GetFavoriteCurrentRequestObject) (GetFavoriteCurrentResponseObject, error)
	// ListTripItems Путевой лист сохранённой поездки
	// (GET /favorites/{id}/items)
	ListTripItems(ctx context.Context, request ListTripItemsRequestObject) (ListTripItemsResponseObject, error)
	// AddTripItem Добавить пункт в путевой лист
	// (POST /favorites/{id}/items)
	AddTripItem(ctx context.Context, request AddTripItemRequestObject) (AddTripItemResponseObject, error)
	// DeleteTripItem Удалить пункт
	// (DELETE /favorites/{id}/items/{item_id})
	DeleteTripItem(ctx context.Context, request DeleteTripItemRequestObject) (DeleteTripItemResponseObject, error)
	// UpdateTripItem Отметить выполненным, переименовать, поменять цену
	// (PATCH /favorites/{id}/items/{item_id})
	UpdateTripItem(ctx context.Context, request UpdateTripItemRequestObject) (UpdateTripItemResponseObject, error)
	// Geocode Поиск адреса (например, квартиры) рядом с городом
	// (GET /geocode)
	Geocode(ctx context.Context, request GeocodeRequestObject) (GeocodeResponseObject, error)
	// GoToHotels Переход на поиск жилья — то же, что /hotels/link, но перенаправлением
	// (GET /hotels/go)
	GoToHotels(ctx context.Context, request GoToHotelsRequestObject) (GoToHotelsResponseObject, error)
	// GetHotelsLink Ссылка на поиск жилья — отели Островка, жильё на Суточно.ру или квартиры посуточно на Авито
	// (GET /hotels/link)
	GetHotelsLink(ctx context.Context, request GetHotelsLinkRequestObject) (GetHotelsLinkResponseObject, error)
	// GetLinkPreview Превью ссылки для путевого листа — название, картинка, цена за сутки
	// (GET /link-preview)
	GetLinkPreview(ctx context.Context, request GetLinkPreviewRequestObject) (GetLinkPreviewResponseObject, error)
	// SearchPlaces Автодополнение точек по названию или IATA-коду
	// (GET /places)
	SearchPlaces(ctx context.Context, request SearchPlacesRequestObject) (SearchPlacesResponseObject, error)
	// GetPlace Точка по идентификатору
	// (GET /places/{id})
	GetPlace(ctx context.Context, request GetPlaceRequestObject) (GetPlaceResponseObject, error)
	// GetPlaceGuide Путеводитель по городу — обзор и места, отобранные авторами Викигида
	// (GET /places/{id}/guide)
	GetPlaceGuide(ctx context.Context, request GetPlaceGuideRequestObject) (GetPlaceGuideResponseObject, error)
	// ListPlacePois Достопримечательности вокруг точки
	// (GET /places/{id}/pois)
	ListPlacePois(ctx context.Context, request ListPlacePoisRequestObject) (ListPlacePoisResponseObject, error)
	// GetPoi Место с подробностями — описание и фото
	// (GET /pois/{type}/{id})
	GetPoi(ctx context.Context, request GetPoiRequestObject) (GetPoiResponseObject, error)
	// GetDriveRoute Линия маршрута на машине между двумя точками по координатам — для карты «Куда угодно»
	// (GET /routes/drive)
	GetDriveRoute(ctx context.Context, request GetDriveRouteRequestObject) (GetDriveRouteResponseObject, error)
	// GetRoadRoute Линия маршрута на машине между двумя точками — для карты
	// (GET /routes/road)
	GetRoadRoute(ctx context.Context, request GetRoadRouteRequestObject) (GetRoadRouteResponseObject, error)
	// ListRoadPois Заправки, кафе и достопримечательности вдоль дороги
	// (GET /routes/road/pois)
	ListRoadPois(ctx context.Context, request ListRoadPoisRequestObject) (ListRoadPoisResponseObject, error)
	// ListStayPrices Ориентировочная цена жилья по городам карты
	// (GET /stay-prices)
	ListStayPrices(ctx context.Context, request ListStayPricesRequestObject) (ListStayPricesResponseObject, error)
	// ListTransfers Как добраться внутри города — например, из аэропорта до квартиры
	// (GET /transfers)
	ListTransfers(ctx context.Context, request ListTransfersRequestObject) (ListTransfersResponseObject, error)
	// SearchTrips Самые дешёвые поездки туда и обратно с учётом дороги до соседних аэропортов
	// (GET /trips)
	SearchTrips(ctx context.Context, request SearchTripsRequestObject) (SearchTripsResponseObject, error)
	// GetWeather Погода на даты поездки в точке
	// (GET /weather)
	GetWeather(ctx context.Context, request GetWeatherRequestObject) (GetWeatherResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

